args:
set -euo pipefail
d="$(mktemp -d "${TMPDIR:-/tmp}/n3.XXXXXX")"
trap 'rm -rf "$d"' EXIT
cat > "$d/n3_test.go" <<'GO'
package report

import (
	"strings"
	"testing"

	"navsvc/pkg/api"
)

func batches() []api.Batch {
	return []api.Batch{{Records: []api.Record{
		{Name: "a", Value: 1, Valid: true},
		{Name: "a", Value: 99, Valid: false},
		{Name: "ghost", Value: 5, Valid: false},
	}}}
}

func TestSummarySkipsInvalid(t *testing.T) {
	out := Aggregate(batches())
	if !strings.Contains(out, "a count=1 total=1") {
		t.Fatalf("invalid record still counted: %q", out)
	}
	if strings.Contains(out, "ghost") {
		t.Fatalf("an entirely invalid name reached the report: %q", out)
	}
}

func TestDistinctSkipsInvalid(t *testing.T) {
	if got := Distinct(batches()); got != 1 {
		t.Fatalf("Distinct counted invalid records: want 1, got %d", got)
	}
}
GO
cp "$d/n3_test.go" internal/report/zz_hidden_n3_test.go
trap 'rm -f internal/report/zz_hidden_n3_test.go; rm -rf "$d"' EXIT
go build ./... > /dev/null
go test ./internal/report/ > /dev/null
git diff --quiet -- legacy/
go test ./internal/pipeline/ ./internal/config/ > /dev/null
